/**
 * Validates a name field for final submission using the shared profile validation rules.
 *
 * @return `true` if valid, `false` otherwise, setting an error message on failure.
 */
private fun validateNameForSubmission(value: String, label: String, maxLength: Int): Boolean {
  val error =
      if (value.isNotBlank() && value.length > maxLength) {
        "$label is too long"
      } else {
        validateProfileName(label, value, maxLength)?.let { profileNameError ->
          when (profileNameError) {
            "$label too long" -> "$label is too long"
            else -> profileNameError
          }
        }
      }

  if (error != null) {
    setErrorMsg(error)
    return false
  }
  return true
}

/**
 * Validates the description field using the shared profile validation rules.
 *
 * @return `true` if valid, `false` otherwise, setting an error message on failure.
 */
private fun validateDescriptionForSubmission(description: String?): Boolean {
  if (description != null && validateProfileDescription(description, InputLimits.DESCRIPTION) != null) {
    setErrorMsg("Description is too long")
    return false
  }
  return true
}

private fun validateNameForUi(name: String, label: String, limit: Int): String? {
  if (name.isNotBlank() && name.length > limit) {
    return "$label is too long"
  }

  return validateProfileName(label, name, limit)?.let { profileNameError ->
    when (profileNameError) {
      "$label too long" -> "$label is too long"
      "Invalid $label format" ->
          "Invalid name format, allowed characters are letters, apostrophes, hyphens, and spaces"
      else -> profileNameError
    }
  }
}

